{
  "findings": [
    {
      "check_id": "CKV_AWS_5",
      "title": "Ensure all data stored in the Elasticsearch is securely encrypted at rest",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "HIGH",
      "explanation": "The `encrypt_at_rest` block explicitly sets `enabled = false`, leaving sensitive log data unencrypted on disk."
    },
    {
      "check_id": "CKV_AWS_6",
      "title": "Ensure all Elasticsearch has node-to-node encryption enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "Node-to-node encryption is not configured, meaning traffic between cluster nodes is transmitted in plaintext within the VPC."
    },
    {
      "check_id": "CKV_AWS_84",
      "title": "Ensure Elasticsearch Domain Logging is enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "No `log_publishing_options` are defined, so access logs and application logs are not being published to CloudWatch or S3 for auditing."
    },
    {
      "check_id": "CKV_AWS_228",
      "title": "Verify Elasticsearch domain is using an up to date TLS policy",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The `domain_endpoint_options` block is missing, defaulting to potentially older TLS policies. Explicitly setting a modern policy like `Policy-Min-TLS-1-2-2019-07` is recommended."
    }
  ],
  "patched_code": "resource "aws_elasticsearch_domain" "log_search_database" {
  domain_name           = "enterprise-log-analytics-es"
  elasticsearch_version = "7.10"

  cluster_config {
    instance_type  = var.elasticsearch_instance_type
    instance_count = 2
  }

  vpc_options {
    subnet_ids         = [aws_subnet.data_subnet_az1.id]
    security_group_ids = [aws_security_group.elasticsearch_sg.id]
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 20
    volume_type = "gp2"
  }

  encrypt_at_rest {
    enabled = true
  }

  node_to_node_encryption {
    enabled = true
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  log_publishing_options {
    cloudwatch_log_group_name = aws_cloudwatch_log_group.es_logs.name
    log_type                  = "INDEX_SLOW_LOGS"
  }

  log_publishing_options {
    cloudwatch_log_group_name = aws_cloudwatch_log_group.es_logs.name
    log_type                  = "SEARCH_SLOW_LOGS"
  }

  log_publishing_options {
    cloudwatch_log_group_name = aws_cloudwatch_log_group.es_logs.name
    log_type                  = "ES_APPLICATION_LOGS"
  }
}

resource "aws_cloudwatch_log_group" "es_logs" {
  name              = "/aws/es/enterprise-log-analytics-es/logs"
  retention_in_days = 30
}",
  "fix_summary": "Enabled encryption at rest and node-to-node encryption. Added a modern TLS security policy and enforced HTTPS. Configured log publishing for index slow logs, search slow logs, and application logs to a new CloudWatch Log Group to satisfy audit logging requirements."
}
